const output = [];
const seen = new Set();
for (const [itemIndex,item] of $input.all().entries()) {
  const root = item.json.body ?? item.json;
  if (root.field && root.field !== 'messages') continue;
  const values = root.entry ? root.entry.flatMap(e => (e.changes ?? []).filter(c => c.field === 'messages').map(c => c.value)) : [root.value ?? root];
  for (const value of values) {
    if (String(value?.metadata?.phone_number_id ?? '') !== 'REPLACE_PHONE_NUMBER_ID') continue;
    for (const message of value.messages ?? []) {
      if (value.group_id || value.metadata?.group_id || message.group_id || message.context?.group_id || message.recipient_type === 'group') continue;
      const sender = String(message.from ?? '');
      const timestamp = Number(message.timestamp);
      if (!/^\d{7,15}$/.test(sender) || !message.id || seen.has(message.id)) continue;
      if (!Number.isFinite(timestamp) || timestamp < Date.now()/1000-86400 || timestamp > Date.now()/1000+300) continue;
      seen.add(message.id);
      output.push({json:{
        sender,messageId:String(message.id),messageType:message.type ?? '',
        choice:String(message.interactive?.button_reply?.id ?? message.interactive?.list_reply?.id ?? message.button?.payload ?? ''),
        text:String(message.text?.body ?? message.button?.text ?? '').trim(),
        senderPhoneId:String(value.metadata.phone_number_id),timestamp
      },pairedItem:{item:itemIndex}});
    }
  }
}
return output;

// Edit this public profile before activating the workflow.
const PROFILE = {
  name:'Your Business',
  portfolio:'https://example.com',
  instagram:'https://www.instagram.com/YOUR_HANDLE/',
  linkedin:'https://www.linkedin.com/in/YOUR_HANDLE/'
};
const {sender,text,choice,messageType,messageId}= $('Normalize Incoming').item.json;
const processed = JSON.parse($json.processed_ids || '[]');
if (processed.includes(messageId)) return null;
const known = $json.welcomed === true || Boolean($getWorkflowStaticData('global').seenSenders?.[sender]);
let flow;
try { flow=JSON.parse($json.flow_state || '{}'); } catch { flow={}; }
if (!flow || typeof flow!=='object' || Array.isArray(flow)) flow={};
flow.answers=flow.answers && typeof flow.answers==='object' && !Array.isArray(flow.answers) ? flow.answers : {};
const focus = raw => {
  const body=raw.replaceAll('BUSINESS_NAME',PROFILE.name).replaceAll('PORTFOLIO_URL',PROFILE.portfolio).replaceAll('INSTAGRAM_URL',PROFILE.instagram).replaceAll('LINKEDIN_URL',PROFILE.linkedin);
  return body.startsWith('*') ? body : body.replace(/^([^\n]*\?)/,'*$1*');
};
const buttons = (body, entries) => ({
  messaging_product:'whatsapp',to:sender,type:'interactive',
  interactive:{type:'button',body:{text:focus(body)},action:{buttons:entries.map(([id,title])=>({type:'reply',reply:{id,title}}))}}
});
const plain = body => ({messaging_product:'whatsapp',to:sender,type:'text',text:{body:focus(body)}});
const list = (body, label, section, entries) => ({
  messaging_product:'whatsapp',to:sender,type:'interactive',
  interactive:{type:'list',body:{text:focus(body)},action:{button:label,sections:[{
    title:section,rows:entries.map(([id,title])=>({id,title}))
  }]}}
});
const main = () => buttons('*How can I help you today?*\nWelcome to BUSINESS_NAME. Choose an option:',[
  ['menu_services','1 My Service'],['menu_quote','2 Get a Quote'],['menu_about','3 About Us']
]);
const about = () => [
  buttons('*What would you like to explore about BUSINESS_NAME?*',[
    ['menu_portfolio','1 View Portfolio'],['menu_social','2 Social Media'],['menu_call','3 Book a Call']
  ]),
  buttons('More about BUSINESS_NAME:',[['menu_faq','4 FAQ'],['menu_main','Main Menu']])
];
const prompts = {
  service:'*Which service do you need?*\nChoose an option or type the service name.',
  details:'*What would you like this service to do?*\nDescribe your project, required features, or any other requirements.',
  budget:'*What is your approximate budget?*\nPlease include the currency. You can also say “not decided”.',
  timeline:'*When would you like the project completed?*\nShare your target date or preferred timeframe.'
};
const ask = () => flow.step==='service'
  ? buttons(prompts.service,[['service_web','Web Development'],['service_ai','AI Automation'],['service_other','Other Service']])
  : plain(prompts[flow.step] || prompts.service);
const resetFlow = () => { flow={last_request:flow.last_request,answers:{}}; };
const acceptService = value => { flow.answers.service=value; flow.step=flow.mode==='quote'?'budget':'details'; };
const back = body => buttons(body,[['menu_main','Main Menu'],['menu_human','Talk to a Person']]);
const faqAnswers = {
  faq_services:'What services are available?\nBUSINESS_NAME offers website development, online stores and AI automation. Choose Our Services from the main menu to share what you need.',
  faq_price:'How much will my project cost?\nA quote depends on your requirements, features and scope. Choose Get a Quote and share your needs, approximate budget and preferred deadline. BUSINESS_NAME must confirm the price.',
  faq_timeline:'How long will my project take?\nThe timeline depends on scope, content readiness and required features. Share your preferred deadline; BUSINESS_NAME must review the requirements and confirm a schedule.',
  faq_start:'What do I need to get started?\nShare a short business description, required pages or features, reference websites, available text/images/logo, approximate budget and preferred deadline.',
  faq_support:'How do I get help with an existing project?\nChoose Existing Customer and share your name, website or project reference, and the update or issue. This assistant cannot access live project records or confirm completion.',
  faq_call:'How do I book a call?\nChoose Book a Call and share your preferred date, time and time zone. BUSINESS_NAME must confirm availability; sending a preference does not book an appointment.'
};
let payload, needsAI=false;
if(choice && !['menu_services','menu_quote','service_web','service_ai','service_other','web_business','web_shop'].includes(choice)) resetFlow();
const serviceNames={service_web:'Web Development',service_ai:'AI Automation',web_business:'Business Website',web_shop:'Online Store'};
if(choice==='menu_main'||/^(hi|hello|start|menu|restart)$/i.test(text)) { resetFlow(); payload=main(); }
else if(choice==='menu_about') { resetFlow(); payload=about(); }
else if(choice==='menu_services'||choice==='menu_quote') {
  flow={last_request:flow.last_request,mode:choice==='menu_quote'?'quote':'service',step:'service',answers:{}};
  payload=ask();
}
else if(Object.prototype.hasOwnProperty.call(serviceNames,choice)||choice==='service_other') {
  if (!flow.mode || !flow.step) flow={last_request:flow.last_request,mode:'service',step:'service',answers:{}};
  if(choice==='service_other') { flow.step='service'; payload=plain('*What service do you need?*\nPlease type the service name.'); }
  else { acceptService(serviceNames[choice]); payload=ask(); }
}
else if(flow.step && !choice) {
  if(messageType!=='text'||!text) payload=ask();
  else if(text.length>600) payload=plain('*Could you shorten your answer to 600 characters?*\n'+prompts[flow.step]);
  else {
    if(flow.step==='service') acceptService(text);
    else if(flow.step==='details'||flow.step==='budget') { flow.answers[flow.step]=text; flow.step='timeline'; }
    else if(flow.step==='timeline') {
      flow.answers.timeline=text;
      const request={type:flow.mode,...flow.answers,received_at:new Date().toISOString()};
      const summary='*Please review your request*\nService: '+request.service+
        (request.type==='quote'?'\nBudget: '+request.budget:'\nDetails: '+request.details)+
        '\nTimeline: '+request.timeline+'\n\nBUSINESS_NAME must review and confirm scope, price and availability. This is not a confirmed quote or booking.';
      flow={last_request:request,answers:{}};
      payload=[plain(summary),...about()];
    } else resetFlow();
    if(!payload) payload=flow.step?ask():main();
  }
}
else if(choice==='menu_human') payload=plain('*How can BUSINESS_NAME help you?*\nPlease share your name, project details and preferred contact time. BUSINESS_NAME must review this conversation before contacting you.');
else if(choice==='menu_portfolio') payload=buttons('Explore BUSINESS_NAME’s portfolio and website:\nPORTFOLIO_URL\n\nType MENU whenever you want to return.',[
  ['menu_call','Book a Call'],['menu_social','Social Media'],['menu_main','Main Menu']]);
else if(choice==='menu_social') payload=buttons('Connect with BUSINESS_NAME:\nInstagram: INSTAGRAM_URL\nLinkedIn: LINKEDIN_URL\n\nChoose a profile below for its link.',[
  ['social_instagram','Instagram'],['social_linkedin','LinkedIn'],['menu_main','Main Menu']]);
else if(choice==='social_instagram') payload=back('Instagram — your profile\nINSTAGRAM_URL');
else if(choice==='social_linkedin') payload=back('LinkedIn — BUSINESS_NAME\nLINKEDIN_URL');
else if(choice==='menu_call') payload=back('*When would you like to speak with BUSINESS_NAME?*\nPlease share your name, what you’d like to discuss, and your preferred date, time and time zone. BUSINESS_NAME must review and confirm availability. This is a call request, not a confirmed appointment.');
else if(choice==='menu_existing') payload=buttons('Welcome back! What do you need help with? This assistant cannot access live project records.',[
  ['existing_update','Project Update'],['existing_change','Request a Change'],['existing_help','Technical Help']]);
else if(choice==='existing_update') payload=back('*What project update do you need?*\nPlease share your name, website or project reference, and the update you need. BUSINESS_NAME must review the conversation to confirm the current project status.');
else if(choice==='existing_change') payload=back('*What would you like changed?*\nPlease share your name, website or project reference, and the changes you need. Include your preferred deadline. BUSINESS_NAME must confirm the scope, cost and schedule.');
else if(choice==='existing_help') payload=back('*What issue are you facing?*\nPlease share your website or project reference, describe the issue and say when it started. You can send a screenshot with a text description. Do not share passwords, API keys or payment details. BUSINESS_NAME must review the issue.');
else if(choice==='menu_faq') payload=list('Frequently asked questions — choose a topic.', 'Choose a Question', 'FAQs',[
  ['faq_services','Services'],['faq_price','Pricing & Quotes'],['faq_timeline','Project Timeline'],
  ['faq_start','Getting Started'],['faq_support','Existing Project Help'],['faq_call','Booking a Call'],['menu_main','Main Menu']]);
else if(Object.prototype.hasOwnProperty.call(faqAnswers,choice)) payload=back(faqAnswers[choice]);
else if(!known && messageType==='text' && text) payload=main();
else if(messageType!=='text' && !choice) payload=plain('Please send a text message or use the menu. Type MENU for options.');
else if(choice) payload=main();
else if(text) needsAI=true;
else return null;
// shortcut: retained IDs cover the latest 100 successful replies per sender; use an atomic ledger for concurrent or high-volume traffic.
return {json:{sender,text,choice,messageId,needsAI,payload,
  welcomed:known || Boolean(text && messageType==='text') || Boolean(choice),
  processed_ids:JSON.stringify([...processed,messageId].slice(-100)),
  flow_state:JSON.stringify(flow),
  last_seen:new Date().toISOString()
}};

const context = $('Route and Build').item.json;
const fallback = 'Sorry, the AI assistant is temporarily unavailable. Please try again or type MENU for options.';
const response = $json.error ? fallback : String($json.output ?? $json.text ?? '').trim() || fallback;
return {json:{payload:{messaging_product:'whatsapp',to:context.sender,type:'text',text:{body:response.slice(0,1000)}}}};
